// Replicates Python's built-in float(str) parsing, as used by
// argparse's type=float conversion.
//
// Python float() accepts:
//   - optional leading/trailing whitespace
//   - an optional sign
//   - "inf" / "infinity" / "nan" (case-insensitive)
//   - decimal literals with optional fraction and exponent
//   - single underscores between digits (PEP 515)

const DIGIT_PART = String.raw`\d(?:_\d)*`;
const FLOAT_RE = new RegExp(
  String.raw`^[+-]?(?:` +
    String.raw`(?:${DIGIT_PART})(?:\.(?:${DIGIT_PART})?)?` + // 12  12.  12.34
    String.raw`|\.(?:${DIGIT_PART})` + //                        .5
  String.raw`)(?:[eE][+-]?(?:${DIGIT_PART}))?$`
);
const SPECIAL_RE = /^([+-]?)(inf(?:inity)?|nan)$/i;

// Returns { ok: true, value: number } or { ok: false }.
export function parsePythonFloat(raw) {
  const s = raw.trim();
  if (FLOAT_RE.test(s)) {
    return { ok: true, value: Number(s.replace(/_/g, '')) };
  }
  const m = SPECIAL_RE.exec(s);
  if (m) {
    if (m[2].toLowerCase() === 'nan') return { ok: true, value: NaN };
    return { ok: true, value: m[1] === '-' ? -Infinity : Infinity };
  }
  return { ok: false };
}

// Minimal decimal arithmetic replicating the semantics of Python's
// Decimal(str(float_value)) as used by moneyed.Money, together with
// the ROUND_HALF_EVEN quantization Babel applies when formatting.
//
// A finite decimal is stored as:
//   { kind: 'finite', sign: -1 | 1, coeff: <digit string, no leading/trailing
//     zeros>, exp: <integer> }
// representing  sign * coeff * 10^exp.
// The sign of zero is preserved (Python keeps Decimal('-0.0')).
// Special values: { kind: 'inf', sign } and { kind: 'nan' }.

export class InvalidOperation extends Error {
  constructor() {
    super("[<class 'decimal.InvalidOperation'>]");
    this.name = 'decimal.InvalidOperation';
  }
}

export function fromNumber(x) {
  if (Number.isNaN(x)) return { kind: 'nan' };
  if (x === Infinity) return { kind: 'inf', sign: 1 };
  if (x === -Infinity) return { kind: 'inf', sign: -1 };

  const sign = x < 0 || Object.is(x, -0) ? -1 : 1;
  const s = Math.abs(x).toString();

  let mant = s;
  let e10 = 0;
  const eIdx = s.indexOf('e');
  if (eIdx >= 0) {
    mant = s.slice(0, eIdx);
    e10 = parseInt(s.slice(eIdx + 1), 10);
  }

  let digits;
  let fracLen = 0;
  const dot = mant.indexOf('.');
  if (dot >= 0) {
    digits = mant.slice(0, dot) + mant.slice(dot + 1);
    fracLen = mant.length - dot - 1;
  } else {
    digits = mant;
  }
  let exp = e10 - fracLen;

  digits = digits.replace(/^0+/, '');
  if (digits === '') {
    return { kind: 'finite', sign, coeff: '0', exp: 0 };
  }
  const trailing = /0+$/.exec(digits);
  if (trailing) {
    digits = digits.slice(0, digits.length - trailing[0].length);
    exp += trailing[0].length;
  }
  return { kind: 'finite', sign, coeff: digits, exp };
}

// -1, 0 or 1. NaN raises, mirroring decimal.InvalidOperation.
export function compare(a, b) {
  if (a.kind === 'nan' || b.kind === 'nan') throw new InvalidOperation();
  if (a.kind === 'inf' || b.kind === 'inf') {
    if (a.kind === 'inf' && b.kind === 'inf') {
      return a.sign === b.sign ? 0 : a.sign < b.sign ? -1 : 1;
    }
    return a.kind === 'inf' ? a.sign : -b.sign;
  }

  const sa = a.coeff === '0' ? 0 : a.sign;
  const sb = b.coeff === '0' ? 0 : b.sign;
  if (sa !== sb) return sa < sb ? -1 : 1;
  if (sa === 0) return 0;

  // Same non-zero sign: compare magnitudes.
  const adjA = a.exp + a.coeff.length;
  const adjB = b.exp + b.coeff.length;
  let mag;
  if (adjA !== adjB) {
    mag = adjA > adjB ? 1 : -1;
  } else {
    const len = Math.max(a.coeff.length, b.coeff.length);
    const pa = a.coeff.padEnd(len, '0');
    const pb = b.coeff.padEnd(len, '0');
    mag = pa === pb ? 0 : pa > pb ? 1 : -1;
  }
  return sa === 1 ? mag : -mag;
}

function addOne(intStr) {
  const digits = intStr.split('');
  let i = digits.length - 1;
  while (i >= 0 && digits[i] === '9') {
    digits[i] = '0';
    i--;
  }
  if (i < 0) return '1' + digits.join('');
  digits[i] = String.fromCharCode(digits[i].charCodeAt(0) + 1);
  return digits.join('');
}

// Rounds |value| to `d` fraction digits using ROUND_HALF_EVEN and returns
// { sign, scaled } where scaled is the resulting integer digit string at
// scale 10^-d. The original sign is kept even when the result is zero
// (Babel prints "-$0.00" for small negative amounts).
export function quantizeHalfEven(dec, d) {
  if (dec.kind !== 'finite') {
    throw new InvalidOperation();
  }
  const k = dec.exp + d;
  let scaled;
  if (k >= 0) {
    scaled = dec.coeff + '0'.repeat(k);
  } else {
    const n = -k; // number of digits to drop
    let kept;
    let dropped;
    if (dec.coeff.length > n) {
      kept = dec.coeff.slice(0, dec.coeff.length - n);
      dropped = dec.coeff.slice(dec.coeff.length - n);
    } else {
      kept = '0';
      dropped = dec.coeff.padStart(n, '0');
    }
    const first = dropped[0];
    let up = false;
    if (first > '5') {
      up = true;
    } else if (first === '5') {
      if (/[1-9]/.test(dropped.slice(1))) {
        up = true;
      } else {
        // Exact tie: round to even.
        const lastKept = kept.charCodeAt(kept.length - 1) - 48;
        if (lastKept % 2 === 1) up = true;
      }
    }
    if (up) kept = addOne(kept);
    scaled = kept;
  }
  scaled = scaled.replace(/^0+(?=\d)/, '');
  return { sign: dec.sign, scaled };
}

// Groups the integer part with thousands separators, en_US style.
export function groupThousands(intStr) {
  return intStr.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

// Reimplements the observable behavior of moneyed.Money:
//   Money(amount_float, currency_code)
//   - the amount is stored as Decimal(str(amount))
//   - the currency code is case-insensitive and must exist
//   - comparison (<) operates on the exact decimal amounts
//   - str(money) formats like Babel's format_currency(amount, code,
//     locale='en_US'): currency symbol, thousands grouping, fraction
//     digits per currency, ROUND_HALF_EVEN, minus sign before the symbol.

import { CURRENCIES } from './currencies.mjs';
import {
  fromNumber,
  compare,
  quantizeHalfEven,
  groupThousands,
} from './decimal.mjs';

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'moneyed.classes.CurrencyDoesNotExist';
    this.code = code;
  }
}

export class Money {
  constructor(amount, currencyCode) {
    const code = String(currencyCode).toUpperCase();
    const meta = CURRENCIES[code];
    if (!meta) {
      throw new CurrencyDoesNotExist(code);
    }
    this.currencyCode = code;
    this.symbol = meta.symbol;
    this.digits = meta.digits;
    this.amount = fromNumber(amount);
  }

  lessThan(other) {
    return compare(this.amount, other.amount) < 0;
  }

  toString() {
    const negative = this.amount.sign < 0;
    if (this.amount.kind === 'inf') {
      return (negative ? '-' : '') + this.symbol + '∞';
    }
    const { scaled } = quantizeHalfEven(this.amount, this.digits);
    let intPart;
    let fracPart = '';
    if (this.digits === 0) {
      intPart = scaled;
    } else if (scaled.length > this.digits) {
      intPart = scaled.slice(0, scaled.length - this.digits);
      fracPart = scaled.slice(scaled.length - this.digits);
    } else {
      intPart = '0';
      fracPart = scaled.padStart(this.digits, '0');
    }
    let out = (negative ? '-' : '') + this.symbol + groupThousands(intPart);
    if (this.digits > 0) out += '.' + fracPart;
    return out;
  }
}

// Minimal re-implementation of the argparse behavior used by test19.py:
//   parser.add_argument('--amount1', type=float, required=True)
//   parser.add_argument('--amount2', type=float, required=True)
//   parser.add_argument('--currency', type=str, required=True)
// plus the implicit -h/--help.
//
// Replicated behaviors: prefix abbreviation of long options, --opt=value
// syntax, the negative-number matcher, error messages and exit codes,
// usage wrapping at the detected terminal width.

import { parsePythonFloat } from './pyfloat.mjs';

const OPTIONS = [
  { names: ['-h', '--help'], dest: 'help', takesValue: false },
  { names: ['--amount1'], dest: 'amount1', takesValue: true, type: 'float', metavar: 'AMOUNT1', required: true },
  { names: ['--amount2'], dest: 'amount2', takesValue: true, type: 'float', metavar: 'AMOUNT2', required: true },
  { names: ['--currency'], dest: 'currency', takesValue: true, type: 'str', metavar: 'CURRENCY', required: true },
];

const LONG_NAMES = OPTIONS.flatMap((o) => o.names.filter((n) => n.startsWith('--')));

// argparse's _negative_number_matcher
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER_RE.test(token);
}

export class ArgparseExit extends Error {
  constructor(code) {
    super(`argparse exit ${code}`);
    this.code = code;
  }
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    const columns = parseInt(process.env.COLUMNS || '', 10);
    this.textWidth = (Number.isInteger(columns) && columns > 0 ? columns : 80) - 2;
  }

  usageParts() {
    return [
      this.prog,
      '[-h]',
      '--amount1', 'AMOUNT1',
      '--amount2', 'AMOUNT2',
      '--currency', 'CURRENCY',
    ];
  }

  formatUsage() {
    const prefix = 'usage: ';
    const oneLine = prefix + this.usageParts().join(' ');
    if (oneLine.length <= this.textWidth) return oneLine + '\n';

    // argparse wraps greedily, keeping "usage: <prog>" on the first line
    // and indenting continuation lines below it.
    const indent = ' '.repeat(prefix.length + this.prog.length + 1);
    const lines = [];
    let line = prefix + this.prog;
    let lineLen = prefix.length - 1; // argparse counts from len(prefix) - 1
    for (const part of this.usageParts()) {
      if (lineLen + 1 + part.length > this.textWidth && line !== prefix) {
        lines.push(line);
        line = indent + part;
        lineLen = indent.length - 1 + 1 + part.length;
      } else {
        line += (line === prefix ? '' : ' ') + part;
        lineLen += 1 + part.length;
      }
    }
    lines.push(line);
    return lines.join('\n') + '\n';
  }

  formatHelp() {
    let out = this.formatUsage() + '\n' + 'options:\n';
    // Help column: min(max_invocation_length + 2, 24) as argparse computes;
    // with these options that is 23 (invocations include the 2-space indent).
    const helpPosition = 23;
    const rows = [
      ['-h, --help', 'show this help message and exit'],
      ['--amount1 AMOUNT1', null],
      ['--amount2 AMOUNT2', null],
      ['--currency CURRENCY', null],
    ];
    for (const [invocation, help] of rows) {
      let line = '  ' + invocation;
      if (help !== null) {
        line = line.padEnd(helpPosition) + help;
      }
      out += line + '\n';
    }
    return out;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new ArgparseExit(2);
  }

  printHelpAndExit() {
    process.stdout.write(this.formatHelp());
    throw new ArgparseExit(0);
  }

  parseArgs(argv) {
    const values = {};
    const extras = [];
    let seenDoubleDash = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (!seenDoubleDash && token === '--') {
        seenDoubleDash = true;
        continue;
      }

      if (!seenDoubleDash && isOptionLike(token)) {
        let name = token;
        let inlineValue = null;
        if (token.startsWith('--')) {
          const eq = token.indexOf('=');
          if (eq >= 0) {
            name = token.slice(0, eq);
            inlineValue = token.slice(eq + 1);
          }
        }

        let option = null;
        if (name.startsWith('--')) {
          option = OPTIONS.find((o) => o.names.includes(name)) || null;
          if (!option) {
            const matches = LONG_NAMES.filter((n) => n.startsWith(name));
            if (matches.length === 1) {
              option = OPTIONS.find((o) => o.names.includes(matches[0]));
            } else if (matches.length > 1) {
              this.error(
                `ambiguous option: ${name} could match ${matches.join(', ')}`
              );
            }
          }
        } else {
          option = OPTIONS.find((o) => o.names.includes(name)) || null;
        }

        if (!option) {
          extras.push(token);
          continue;
        }

        if (!option.takesValue) {
          this.printHelpAndExit();
        }

        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
        } else {
          const next = argv[i + 1];
          if (next === undefined || isOptionLike(next) || next === '--') {
            this.error(`argument ${option.names[0]}: expected one argument`);
          }
          raw = next;
          i++;
        }

        if (option.type === 'float') {
          const parsed = parsePythonFloat(raw);
          if (!parsed.ok) {
            this.error(
              `argument ${option.names[0]}: invalid float value: '${raw}'`
            );
          }
          values[option.dest] = parsed.value;
        } else {
          values[option.dest] = raw;
        }
      } else {
        extras.push(token);
      }
    }

    const missing = OPTIONS.filter(
      (o) => o.required && !(o.dest in values)
    ).map((o) => o.names[0]);
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.join(', ')}`
      );
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

